	args := []string{
		"exec",
		"--cwd", workDir,
		"--auto", r.AutoLevel,
		"-o", "text",
	}

	if len(tools) > 0 {
		args = append(args, "--enabled-tools", strings.Join(tools, ","))
	}

	if r.Model != "" {
		args = append(args, "-m", r.Model)
	}

	args = append(args, prompt)

	ctx, cancel := context.WithTimeout(ctx, r.Timeout)
